#!/usr/bin/env python3
"""relay 105 (analysis-fanout 082): S9 field-read keys; S14 rq2.ledger retirement + three new rq2.crown.units keys + corrected CROWN provenances;
S15 rq5.pair provenance notes; S16 return-port keys; S17 premise keys."""
import re, sys
NR = sys.argv[1]
FR = 'at the frame of record L01^14 (landed 2026-10-06, R852-1): census scratch/main/frame14 (code 4a47f16f7, analysis frame era5c-l01p14-v1), L01^14 solve era5c-l01p14-restored-solve; analysis-fanout 082 (relay 105). '
lines = open(NR).read().split('\n'); idx = {}
for i, l in enumerate(lines):
    m = re.match(r'^\| ([A-Za-z][A-Za-z0-9._-]*) \|', l)
    if m: idx[m.group(1)] = i
def cells(k): return [x.strip() for x in lines[idx[k]].split('|')]
def setrow(k, v, status, prov, layer=None, unit=None, append=False):
    assert '|' not in prov + v, k
    if k in idx:
        c = cells(k); layer = layer or c[4]; unit = unit or c[5]
        p = (c[6] + ' ' + prov) if append else prov
        lines[idx[k]] = f'| {k} | {v} | {status} | {layer} | {unit} | {p} |'
    else:
        lines.insert(len(lines) - (1 if lines[-1] == '' else 0), f'| {k} | {v} | {status} | {layer} | {unit} | {prov} |')
        idx[k] = len(lines) - 2
def replace_in(k, old, new):
    c = cells(k); assert old in c[6], (k, old); c6 = c[6].replace(old, new)
    lines[idx[k]] = f'| {k} | {c[2]} | {c[3]} | {c[4]} | {c[5]} | {c6} |'
# --- S9
setrow('analysis.lend.field-read.candidates', '38', 'pending', FR + 'Era 5b\'s licensing field-reader arm (spec §3.10.7; on under CRAT_ERA5B_PASS=joint with CRAT_ERA5B_REPAIR unset, no switch of its own: licensing/facts.rs:164-173, coherence.rs:177-185, solver.rs:4732, mod.rs:732-735): reader candidates = exact field loads q = (*p).f into an unprojected raw-pointer local inside a function certified read-only (readers.rs:622-626, 230-235); 38 in 6 programs (quadtree 26, avl 4, json.h 4, bst 2, heman 1, lil 1), 13 with the transfer represented, 25 missing (8 CopyForDeref, all quadtree; 17 plain loads). Read from each L01^14 cache entry\'s reader keys in bounded chunks (agents/artifacts/2026-10-06-analysis-fanout-082/s9/readers.py). Same as L01^13 (era-5c 124). Re-read at the next frame of record.')
setrow('analysis.lend.field-read.taken', '2', 'pending', FR + 'Of the 38 candidates, the sites whose guard r = ref(view) AND own(field) (solver.rs:1142-1153) is true in the accepted model: 2 in 2 functions, bst minValueNode bb7[2] _9 = (*_1).left and avl minValueNode bb4[2] _7 = (*_1).left; the accepted round\'s receipts exports.reader_replay hold exactly these two (reader_replay.rs:196-265). Both views are compiler temporaries (not census subjects); each moves into the formal node#1, delivered (bst optional, avl ref; emitted bst lib.rs:78, avl lib.rs:163). Both rest on the classified support clause, which exists only under CRAT_ERA5B_INTERFACE_OWN=on (solver.rs:2345; avl also needs CRAT_ERA5C_MOVED_INPUT and CRAT_ERA5C_ORIGIN_SET). Same as L01^13.')
