setrow('rq5.pair.clear.classifier', cells('rq5.pair.clear.classifier')[2], 'pending', 'NOTE (analysis-fanout 081 / 082): 4 of the 72 are FALSE clears -- libzahl zmul\'s zadd / zsub sites pass the same expression x.as_mut_ptr() twice and the A5 classifier receipts clear:a5-proven-disjoint (UB under Tree Borrows and Stacked Borrows on a reproduction; report 081).', append=True)
